; apx_ndd.asm -- APX EVEX map 4: NDD, {nf}, {evex} (Phase 3, include/iset/apx.inc)
;
; Environment
;	Assembly-time only: nothing here is executed (no APX processor is public
;	yet). fasmg assembles each instruction inside VIRTUAL and compares the
;	bytes (reference: llvm-mc 23 with -mattr=+ndd,+nf,+egpr, generated by
;	tests/iset/_apx_diff.py, which moves {nf} before the mnemonic for llvm);
;	a mismatch stops assembly with 'encoding mismatch'. The failure cases at
;	the end are each assembled alone by _run.ps1 (-i"FAIL=n") and must stop
;	with the quoted message. By hand:  fasm2 apx_ndd.asm apx_ndd.bin
;
; What is new
;	The legacy integer instructions promoted to EVEX map 4 (spec 355828
;	3.1.2.3.1): a new data destination (one operand more, written first),
;	{nf} after the mnemonic (no flags update), and {evex}. apx.inc stacks a
;	layer over each mnemonic; forms with none of these pass straight to the
;	earlier definition, the others call it again with x86.apx.* set, and
;	x86.store_instruction writes 62 [~R3 ~X3 ~B3 ~R4 B4 100] [W ~V3-V0 ~X4 pp]
;	[0 0 0 ND ~V4 NF 0 0] where it writes REX/REX2. Failure modes this file
;	guards against:
;	- the legacy forms keep their bytes, including the accumulator short
;	  forms (04h/05h), which have no EVEX form and so become 80h-83h there;
;	- operand roles: add ndd, r/m, reg is 01 /r; add ndd, reg, r/m is 03 /r;
;	- map 1 opcodes move: imul AF, shld 24/A5, shrd 2C/AD, popcnt 88,
;	  tzcnt F4, lzcnt F5 (F3 dropped); 66h becomes pp = 01;
;	- X4 is the inverted U bit (index r16-r31), B4 is not inverted;
;	- an unsized memory source takes the NDD's size (inc r16, [rax]);
;	- imul r, r/m, imm stays legacy; imul ndd, r, r/m is the NDD form;
;	- LOCK/REP before EVEX #UD; ah-bh do not exist in map 4.
;
; FAIL 1: '{nf} not supported by this instruction'
; FAIL 2: '{nf} not supported by this instruction'
; FAIL 3: 'unknown instruction option'
; FAIL 4: 'operand sizes do not match'
; FAIL 5: 'disallowed combination of registers'
; FAIL 6: 'prefix not allowed with EVEX'
; FAIL 7: 'prefix not allowed with EVEX'
; FAIL 8: 'APX_F or higher required'
; FAIL 9: 'bits64 or higher required'
; FAIL 10: 'invalid new data destination'
; FAIL 11: 'POPCNT required'
; FAIL 12: 'extra characters on line'
; FAIL 13: 'invalid combination of operands'

macro expect bytes*, line&
	local n, got, k, want
	virtual at 0
		line
		n = $
		load got:n from 0
	end virtual
	virtual at 0
		db bytes
		k = $
		load want:k from 0
	end virtual
	if n <> k | got <> want
		display 'FAIL: ', `line, 13, 10
		err 'encoding mismatch'
	end if
end macro

use64
use everything

if ~ defined FAIL
	expect <62h,0F4h,0FCh,18h,01h,0CBh>, add rax, rbx, rcx
	expect <62h,0F4h,0FCh,10h,01h,0D8h>, add r16, rax, rbx
	expect <62h,0FCh,0FCh,18h,01h,0D8h>, add rax, r16, rbx
	expect <62h,0E4h,0FCh,18h,01h,0C3h>, add rax, rbx, r16
	expect <62h,4Ch,84h,10h,01h,0EEh>, add r31, r30, r29
	expect <62h,0F4h,7Ch,18h,01h,0CBh>, add eax, ebx, ecx
	expect <62h,0F4h,7Dh,18h,01h,0CBh>, add ax, bx, cx
	expect <62h,0F4h,7Ch,18h,00h,0CBh>, add al, bl, cl
	expect <62h,0F4h,7Ch,10h,00h,0FCh>, add r16b, spl, dil
	expect <62h,0F4h,0FCh,18h,01h,0Bh>, add rax, [rbx], rcx
	expect <62h,0F4h,0FCh,18h,03h,0Bh>, add rax, rcx, [rbx]
	expect <62h,0FCh,0F8h,18h,01h,4Ch,0ACh,08h>, add rax, [r20+r21*4+8], rcx
	expect <62h,0F4h,0F8h,18h,01h,0Ch,0A0h>, add rax, [rax+r20*4], rcx
	expect <62h,0B4h,0FCh,18h,01h,0Ch,20h>, add rax, [rax+r12], rcx
	expect <62h,0F4h,0FCh,18h,83h,0C3h,01h>, add rax, rbx, 1
	expect <62h,0F4h,0FCh,18h,81h,0C3h,78h,56h,34h,12h>, add rax, rbx, 12345678h
	expect <62h,0F4h,7Ch,18h,81h,0C3h,00h,10h,00h,00h>, add eax, ebx, 1000h
	expect <62h,0F4h,7Ch,18h,80h,0C3h,05h>, add al, bl, 5
	expect <62h,0F4h,0FCh,18h,83h,03h,01h>, add rax, qword [rbx], 1
	expect <62h,0F4h,0FCh,18h,83h,0C3h,0FFh>, add rax, rbx, -1
	expect <62h,0F4h,0FCh,0Ch,01h,0D8h>, add {nf} rax, rbx
	expect <62h,0F4h,0FCh,1Ch,01h,0CBh>, add {nf} rax, rbx, rcx
	expect <62h,0F4h,0FCh,0Ch,83h,0C0h,01h>, add {nf} rax, 1
	expect <62h,0F4h,7Ch,0Ch,81h,0C0h,78h,56h,34h,12h>, add {nf} eax, 12345678h
	expect <62h,0F4h,7Ch,0Ch,80h,0C0h,05h>, add {nf} al, 5
	expect <62h,0F4h,0FCh,0Ch,01h,18h>, add {nf} [rax], rbx
	expect <62h,0F4h,0FCh,0Ch,83h,00h,01h>, add {nf} qword [rax], 1
	expect <62h,0F4h,0FCh,08h,01h,0D8h>, {evex} add rax, rbx
	expect <62h,0F4h,7Ch,08h,83h,0C0h,01h>, {evex} add eax, 1
	expect <62h,0F4h,0FCh,18h,09h,0CBh>, or rax, rbx, rcx
	expect <62h,0ECh,7Ch,0Ch,21h,0C8h>, and {nf} r16d, r17d
	expect <62h,0F4h,0FCh,18h,2Bh,59h,08h>, sub rax, rbx, [rcx+8]
	expect <62h,0F4h,7Dh,0Ch,31h,0D8h>, xor {nf} ax, bx
	expect <62h,0F4h,0FCh,18h,11h,0CBh>, adc rax, rbx, rcx
	expect <62h,0F4h,0FCh,10h,83h,0D8h,01h>, sbb r16, rax, 1
	expect <62h,0F4h,0FCh,18h,0FFh,0C3h>, inc rax, rbx
	expect <62h,0F4h,0FCh,0Ch,0FFh,0C0h>, inc {nf} rax
	expect <62h,0F4h,0FCh,10h,0FFh,00h>, inc r16, [rax]
	expect <62h,0FCh,7Ch,0Ch,0FEh,0C8h>, dec {nf} r16b
	expect <62h,0F4h,0FCh,18h,0F7h,0DBh>, neg rax, rbx
	expect <62h,0F4h,0FCh,0Ch,0F7h,18h>, neg {nf} qword [rax]
	expect <62h,0F4h,0FCh,18h,0F7h,0D3h>, not rax, rbx
	expect <62h,0F4h,7Ch,10h,0F7h,10h>, not r16d, [rax]
	expect <62h,0F4h,0FCh,0Ch,0F7h,0E3h>, mul {nf} rbx
	expect <62h,0FCh,0FCh,0Ch,0F7h,0F0h>, div {nf} r16
	expect <62h,0F4h,7Ch,0Ch,0F7h,38h>, idiv {nf} dword [rax]
	expect <62h,0F4h,0FCh,18h,0D3h,0E3h>, shl rax, rbx, cl
	expect <62h,0F4h,0FCh,18h,0D1h,0E3h>, shl rax, rbx, 1
	expect <62h,0F4h,0FCh,18h,0C1h,0E3h,05h>, shl rax, rbx, 5
	expect <62h,0F4h,0FCh,0Ch,0D3h,0E0h>, shl {nf} rax, cl
	expect <62h,0F4h,0FCh,0Ch,0D1h,0E0h>, shl {nf} rax, 1
	expect <62h,0F4h,0FCh,10h,0C1h,38h,03h>, sar r16, [rax], 3
	expect <62h,0F4h,0FCh,18h,0C1h,0E3h,02h>, sal rax, rbx, 2
	expect <62h,0FCh,7Ch,0Ch,0D2h,0E8h>, shr {nf} r16b, cl
	expect <62h,0F4h,0FCh,18h,0C1h,0C3h,04h>, rol rax, rbx, 4
	expect <62h,0F4h,7Ch,0Ch,0D1h,0C8h>, ror {nf} eax, 1
	expect <62h,0F4h,0FCh,18h,0D3h,0D3h>, rcl rax, rbx, cl
	expect <62h,0F4h,0FCh,18h,0D1h,0DBh>, rcr rax, rbx, 1
	expect <62h,0F4h,0FCh,18h,24h,0CBh,05h>, shld rax, rbx, rcx, 5
