	expect <62h,0F4h,0FCh,10h,2Ch,0D8h,01h>, shrd r16, rax, rbx, 1
	expect <62h,0F4h,0FCh,18h,0AFh,0D9h>, imul rax, rbx, rcx
	expect <62h,0F4h,0FCh,18h,0AFh,19h>, imul rax, rbx, [rcx]
	expect <62h,0F4h,0FCh,0Ch,0AFh,0C3h>, imul {nf} rax, rbx
	expect <62h,0F4h,0FCh,0Ch,6Bh,0C3h,0Ah>, imul {nf} rax, rbx, 10
	expect <62h,0F4h,0FCh,0Ch,69h,0C3h,00h,10h,00h,00h>, imul {nf} rax, rbx, 1000h
	expect <62h,0F4h,0FCh,0Ch,0F7h,0EBh>, imul {nf} rbx
	expect <62h,0F4h,7Dh,0Ch,0AFh,0C3h>, imul {nf} ax, bx
	expect <62h,0F4h,0FCh,0Ch,88h,0C3h>, popcnt {nf} rax, rbx
	expect <62h,0E4h,7Ch,0Ch,0F5h,00h>, lzcnt {nf} r16d, [rax]
	expect <62h,0F4h,7Dh,0Ch,0F4h,0C3h>, tzcnt {nf} ax, bx
	expect <62h,0F4h,0FCh,08h,88h,0C3h>, {evex} popcnt rax, rbx
	expect <62h,0F4h,0FCh,08h,0AFh,0C3h>, {evex} imul rax, rbx
	expect <62h,0F4h,7Dh,18h,0F7h,5Bh,08h>, neg ax, [rbx+8]
	expect <62h,0F4h,74h,10h,80h,00h,01h>, add r17b, [rax], 1
	expect <62h,0F4h,0FCh,18h,24h,0Bh,01h>, shld rax, [rbx], rcx, 1
	expect <0F0h,48h,01h,18h>, lock add [rax], rbx
	expect <05h,78h,56h,34h,12h>, add eax, 12345678h
	expect <04h,05h>, add al, 5
	expect <48h,83h,0C0h,01h>, add rax, 1
	expect <48h,6Bh,0C3h,0Ah>, imul rax, rbx, 10
	expect <48h,0Fh,0A4h,0D8h,05h>, shld rax, rbx, 5
	expect <48h,0FFh,0C0h>, inc rax
	expect <0F3h,48h,0Fh,0B8h,0C3h>, popcnt rax, rbx
	expect <48h,01h,0D8h>, add rax, rbx

else if FAIL = 1	; NDD only: adc, sbb, not, rcl, rcr
	adc {nf} rax, rbx

else if FAIL = 2
	not {nf} rax

else if FAIL = 3	; {zu} is not implemented yet (Phase 4)
	add {zu} rax, rbx

else if FAIL = 4	; the NDD has the operation's size
	add r16d, rax, rbx

else if FAIL = 5	; no ah-bh in EVEX map 4
	add ah, bl, cl

else if FAIL = 6	; LOCK/REP before EVEX: #UD
	lock add {nf} [rax], rbx

else if FAIL = 7
	rep add {nf} rax, rbx

else if FAIL = 8
	use i386, x64
	add rax, rbx, rcx

else if FAIL = 9
	use32
	add eax, ebx, ecx

else if FAIL = 10	; the NDD is a register
	add [rax], rbx, rcx

else if FAIL = 11	; plus the instruction's own feature
	use i386, x64, APX_F
	popcnt {nf} rax, rbx

else if FAIL = 12	; mul has no NDD form
	mul rax, rbx

else if FAIL = 13	; imul ndd, r, r/m: the first source is a register
	imul rax, [rbx], rcx

end if